{
  "description": "The creature is depicted in right-facing side profile standing on a patch of rocky ground. It has the overall size, posture, and fur of a wolf, but most of its body is covered in heavy, segmented, armor-like plating. The head, neck ruff, chest, belly fringe, and lower front legs show thick gray, white and tan wolf fur, while the back, sides, shoulders, hips, tail and much of all four legs are encased in overlapping dark slate-gray plates with tan edges. A paler cream-colored segmented underlayer with rows of oval holes is exposed along the mid-flank between the dorsal plates and the belly fur. The tail is long and fully armored, and the four clawed paws are visible at the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a wolf head in profile facing right, with dense gray fur on the crown, lighter gray-white on the muzzle and cheek, a black nose at the tip of the snout, a visible amber eye, and fine whiskers",
      "where": "at the front right end of the body, attached to the furry neck"
    },
    {
      "part": "ears",
      "looks_like": "two upright, triangular, pointed ears with dark outer fur and lighter inner fur detailing",
      "where": "on top of the head, one slightly behind the other in side view"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, long fur in mixed gray, white and beige tones forming a ruff",
      "where": "encircling the neck from behind the ears down over the throat and chest, between the head and the plated torso"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, jointed legs; the front pair mostly fur-covered on the lower half with dark segmented plates over the shoulders and upper forelegs, the hind pair more extensively covered in overlapping dark plates with visible joints at the knee and hock",
      "where": "beneath the torso, two in front under the chest and two in back under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four wolf-like paws with fur, distinct toes, and dark curved claws",
      "where": "at the bottom ends of the four legs, in contact with the rocky ground"
    },
    {
      "part": "tail",
      "looks_like": "a long, tapering, heavily armored tail covered in overlapping dark plates with a row of small pointed spines along the lower edge, curving downward toward the tip",
      "where": "extending from the rear of the torso behind the hind legs"
    },
    {
      "part": "plates",
      "looks_like": "overlapping, glossy, hard-looking segmented plates in dark slate-gray to black with tan rims and weathered highlights; dorsal plates are large and band-like across the back, shoulder and hip plates are broader and layered, leg plates are ring-like segments, and tail plates are small overlapping rings; along the flank a paler cream-colored segmented layer with two rows of oval perforations and small pits is exposed beneath the dorsal plates",
      "where": "covering the top and sides of the neck behind the fur, the entire back from shoulders to tail base, the sides of the torso, the outer shoulders and hips, most of the hind legs, the upper front legs, and the entire tail"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "isopod"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
